    var token = JWTToken.decode(compact, null, jwksJson);

    assertThat(token.isSignatureValid()).isTrue();
    assertThat(token.getHeader()).contains("\"kid\" : \"kid-1\"");
  }

  @Test
  @SneakyThrows
